<script setup lang="ts">
import { useI18n } from 'vue-i18n'
import type { ChartRow } from '@/api/adminDashboard'
defineProps<{rows?:ChartRow[];loading?:boolean;refreshedAt?:string}>();const emit=defineEmits<{(e:'refresh'):void;(e:'interval',value:number):void}>();const{t}=useI18n();function hasValue(value:unknown){return value!==null&&value!==undefined&&value!==''}
</script><template><el-card class="section-card realtime-panel" shadow="never" v-loading="loading"><template #header><div class="section-header"><h3 class="section-title">{{ t('dashboardBI.sections.realtime') }}</h3><div class="realtime-actions"><span>{{ refreshedAt ? new Date(refreshedAt).toLocaleTimeString() : '-' }}</span><el-select :model-value="60" style="width:120px" @change="emit('interval',$event)"><el-option :label="t('dashboardBI.refresh.manual')" :value="0"/><el-option :label="t('dashboardBI.refresh.seconds30')" :value="30"/><el-option :label="t('dashboardBI.refresh.seconds60')" :value="60"/><el-option :label="t('dashboardBI.refresh.minutes5')" :value="300"/></el-select><el-button @click="emit('refresh')">{{ t('common.refresh') }}</el-button></div></div></template><div class="realtime-grid"><div v-for="row in rows" :key="String(row.key)" class="realtime-item"><span>{{ t(`dashboardBI.metrics.${row.key}`) }}</span><strong>{{ hasValue(row.value) ? row.value : '-' }}<small v-if="hasValue(row.value)&&String(row.key).includes('Rate')">%</small></strong></div></div></el-card></template>
<style scoped>.realtime-actions{display:flex;align-items:center;gap:10px;color:#909399;font-size:12px}.realtime-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px}.realtime-item{padding:14px;border:1px solid #ebeef5;border-radius:5px;background:#fafafa}.realtime-item span{display:block;color:#606266;font-size:12px}.realtime-item strong{display:block;margin-top:8px;color:#303133;font-size:20px}.realtime-item small{font-size:12px}@media(max-width:1000px){.realtime-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:640px){.realtime-grid{grid-template-columns:1fr}.section-header{align-items:flex-start;gap:12px}.realtime-actions{flex-wrap:wrap}}</style>
